def tcp_handshake(states):
    # TCP 三次握手：CLOSED → SYN → SYN-ACK → ESTABLISHED
    # 生效条件：states 为事件序列（SYN/SYN-ACK/ACK 等）
    # 子功能：① 状态机迁移 ② 非法事件忽略 ③ 到达 ESTABLISHED 判定
    # 执行：状态转移表逐事件推进
    # 不适用条件：输入不满足生效条件时返回 None/不执行
    state = 'CLOSED'
    for ev in states:
        if state == 'CLOSED' and ev == 'SYN':
            state = 'SYN_SENT'
        elif state == 'SYN_SENT' and ev == 'SYN-ACK':
            state = 'ESTABLISHED'
    return state

