def vm_run_loop(code, symbols=None, max_steps=1000):
    # 智能论 VM 循环执行：算术(ADD/SUB)+比较+回跳；步数上限防死循环
    ip, stack = 0, []
    symbols = dict(symbols or {})
    steps = 0
    while ip < len(code):
        steps += 1
        if steps > max_steps:
            return {'error': '循环未终止（超出步数上限）',
                    'symbols': symbols, 'stack': stack}
        op, arg = code[ip]
        ip += 1
        if op == 'PUSH':
            stack.append(arg)
        elif op == 'STORE':
            symbols[arg] = stack.pop()
        elif op == 'LOAD':
            if arg not in symbols:
                return {'error': '名实不符：' + arg,
                        'symbols': symbols, 'stack': stack}
            stack.append(symbols[arg])
        elif op == 'JUMP_IF_FALSE':
            v = stack.pop() if stack else False
            if v is False or v is None or v == 0:
                ip = arg
        elif op == 'JUMP':
            ip = arg
        elif op == 'CMP_LT':
            b, a = stack.pop(), stack.pop()
            stack.append(a < b)
        elif op == 'ADD':
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif op == 'SUB':
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
    return {'error': None, 'symbols': symbols, 'stack': stack}

