def shortest_path(graph, start, end):
    # 无权图最短路径：BFS 逐层扩散 + 前驱还原（最少条件链跳数）
    if start == end:
        return [start]
    from collections import deque
    prev = {start: None}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        for nxt in graph.neighbors(cur):
            if nxt not in prev:
                prev[nxt] = cur
                if nxt == end:
                    path = []
                    node = nxt
                    while node is not None:
                        path.append(node)
                        node = prev[node]
                    return path[::-1]
                queue.append(nxt)
    return None

domain:graph|图遍历-加权最短.code:
def dijkstra(graph, weights, start, end):
    # 加权最短路径：Dijkstra 贪心（权重=条件链代价/信任度倒数，小=优）
    import heapq
    dist = {start: 0}
    prev = {start: None}
    pq = [(0, start)]
    while pq:
        d, cur = heapq.heappop(pq)
        if d > dist.get(cur, float('inf')):
            continue
        if cur == end:
            break
        for nxt in graph.neighbors(cur):
            w = weights.get((cur, nxt), 1)
            nd = d + w
            if nd < dist.get(nxt, float('inf')):
                dist[nxt] = nd
                prev[nxt] = cur
                heapq.heappush(pq, (nd, nxt))
    if end not in dist:
        return None
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = prev[node]
    return path[::-1], dist[end]

