def classify_page_fault(vpn, page_table, access):
    # 页面错误分类：未映射/未驻留/写保护 → 错误类型（MMU 语义）
    entry = page_table.get(vpn)
    if entry is None:
        return 'segment_fault'      # 非法地址（未映射）
    if entry.get('present') != 1:
        return 'minor_fault'        # 缺页（软缺页：磁盘→内存）
    if access == 'write' and not entry.get('writable'):
        return 'protection_fault'   # 写保护违例
    return 'ok'

