def sliding_window(base, next_seq, window_size, ack):
    # TCP 滑动窗口：收到 ack 后窗口前移（可发送序号 = [next_seq, base+win)）
    # base=已确认序号 next_seq=下一待发 ack=收到的确认
    if ack > base:
        base = ack
    if next_seq < base:
        next_seq = base
    return {'base': base, 'next_seq': next_seq,
            'window': [base + i for i in range(window_size)]}

