def chain_query(graph, condition, max_len=4):
    # 图查询语言：从条件出发沿边收集完整链（MATCH (a)-[*]->(b) 路径语义）
    chains = []
    def walk(cur, path):
        if len(path) > max_len:
            return
        succ = graph.neighbors(cur)
        if not succ:
            chains.append(list(path))
            return
        for nxt in succ:
            if nxt not in path:
                path.append(nxt)
                walk(nxt, path)
                path.pop()
    walk(condition, [condition])
    return sorted(chains)

