def txn_op(state, op, payload=None):
    # 图数据库事务：begin 快照 / commit 生效 / rollback 回滚（ACID 原子性）
    if op == 'begin':
        state['snapshot'] = {k: list(v) if isinstance(v, list) else v
                              for k, v in state.get('data', {}).items()}
        return 'active'
    if op == 'commit':
        state['snapshot'] = None
        return 'committed'
    if op == 'rollback':
        if 'snapshot' in state and state['snapshot'] is not None:
            state['data'] = state['snapshot']
            state['snapshot'] = None
        return 'rolled_back'
    return 'idle'

