def pagerank(graph, iterations=5, damping=0.85):
    # PageRank：权重迭代传播（出链均分，阻尼因子防死端）
    nodes = sorted(graph.nodes)
    n = len(nodes)
    pr = {node: 1.0 / n for node in nodes}
    for _ in range(iterations):
        new_pr = {node: (1 - damping) / n for node in nodes}
        for node in nodes:
            out = graph.neighbors(node)
            if not out:
                continue
            share = damping * pr[node] / len(out)
            for nxt in out:
                new_pr[nxt] += share
        pr = new_pr
    return pr

domain:graph|图算法-连通分量.code:
def connected_components(graph):
    # 无向连通分量：BFS 分组（边双向视为连通，互达节点同组）
    from collections import deque
    # 构建无向邻接（edges 双向化）
    adj = {n: set(graph.neighbors(n)) for n in graph.nodes}
    for n in list(graph.nodes):
        for nxt in graph.neighbors(n):
            adj.setdefault(nxt, set()).add(n)
    seen = set()
    comps = []
    for start in sorted(graph.nodes):
        if start in seen:
            continue
        group = set()
        queue = deque([start])
        seen.add(start)
        while queue:
            cur = queue.popleft()
            group.add(cur)
            for nxt in adj.get(cur, set()):
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
        comps.append(sorted(group))
    return sorted(comps)

