def topological_sort(graph):
    # 拓扑排序：DAG 依赖顺序（Kahn 算法——入度归零先出）
    from collections import deque
    indeg = {node: 0 for node in graph.nodes}
    for node in graph.nodes:
        for nxt in graph.neighbors(node):
            indeg[nxt] = indeg.get(nxt, 0) + 1
    queue = deque(sorted(n for n, d in indeg.items() if d == 0))
    order = []
    while queue:
        cur = queue.popleft()
        order.append(cur)
        for nxt in graph.neighbors(cur):
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                queue.append(nxt)
    return order if len(order) == len(graph.nodes) else None

