def process_tree(parents, root):
    # 进程树：父进程关系 → 后代集合（递归收集子树）
    children = {}
    for pid, ppid in parents.items():
        children.setdefault(ppid, []).append(pid)
    desc = []
    def walk(pid):
        for c in children.get(pid, []):
            desc.append(c)
            walk(c)
    walk(root)
    return sorted(desc)

