def graph_isomorphic(edges_a, edges_b):
    # 图同构（简化）：边数+节点度序列 相同 → 可能同构（必要条件）
    def deg_seq(edges):
        nodes = set()
        for s, d in edges:
            nodes.add(s)
            nodes.add(d)
        deg = {n: 0 for n in nodes}
        for s, d in edges:
            deg[s] += 1
            deg[d] += 1
        return len(nodes), sorted(deg.values())
    return deg_seq(edges_a) == deg_seq(edges_b)

