def label_propagation(graph, iterations=3):
    # 社区发现：标签传播（LPA——节点取邻居多数标签收敛）
    labels = {n: n for n in graph.nodes}
    for _ in range(iterations):
        for n in sorted(graph.nodes):
            neigh = graph.neighbors(n)
            if not neigh:
                continue
            from collections import Counter
            cnt = Counter(labels[x] for x in neigh)
            labels[n] = cnt.most_common(1)[0][0]
    return labels

