def force_layout(nodes, edges, iterations=2):
    # 力导向布局：斥力+引力迭代（节点坐标稳定——图可视化）
    pos = {n: i * 1.0 for i, n in enumerate(nodes)}  # 初始线性
    for _ in range(iterations):
        for a in nodes:
            for b in nodes:
                if a != b and pos[a] < pos[b]:
                    pos[a] += 0.1  # 斥力推远
                    pos[b] -= 0.1
        for a, b in edges:
            pos[b] = (pos[a] + pos[b]) / 2  # 引力拉近
    return {n: round(pos[n], 2) for n in nodes}

