def layer_layout(graph):
    # 分层布局：按 BFS 深度分层（层次坐标——层级图可视化）
    from collections import deque
    starts = [n for n in graph.nodes if not any(
        n in graph.neighbors(m) for m in graph.nodes)]
    if not starts:
        starts = [min(graph.nodes)]
    layers = {}
    for s in starts:
        q = deque([(s, 0)])
        while q:
            n, d = q.popleft()
            if n not in layers or d < layers[n]:
                layers[n] = d
            for nxt in graph.neighbors(n):
                if nxt not in layers or d + 1 < layers[nxt]:
                    q.append((nxt, d + 1))
    return layers

