def health_check(graph):
    # 健康检查：无向连通（正反向边都走）+ 无孤立节点（可用性判定）
    if not graph.nodes:
        return ('ok', True)
    # 无向邻接（正向+反向边）
    adj = {n: set(graph.neighbors(n)) for n in graph.nodes}
    for n in graph.nodes:
        for nxt in graph.neighbors(n):
            adj.setdefault(nxt, set()).add(n)
    visited = set()
    stack = [next(iter(graph.nodes))]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        stack.extend(adj.get(cur, set()))
    if len(visited) != len(graph.nodes):
        return ('isolated', False)
    return ('ok', True)

