def shm_ops(segments, key, op, offset=0, value=None, size=0):
    # 共享内存：attach 挂接 / write 写偏移 / read 读偏移 / detach 释放
    # （多进程映射同一物理页，引用计数）
    if op == 'attach':
        if key not in segments:
            segments[key] = {'data': bytearray(size), 'refs': 0}
        segments[key]['refs'] += 1
        return segments[key]['refs']
    if op == 'write':
        segments[key]['data'][offset] = value
        return value
    if op == 'read':
        return segments[key]['data'][offset]
    if op == 'detach':
        segments[key]['refs'] -= 1
        return segments[key]['refs']
    return None

