def cache_strategy(strategy, cache, url, network_ok=True):
    # PWA 缓存策略：cache-first 缓存优先 / network-first 网络优先
    # / stale 陈旧再验证（离线可用性策略）
    cached = cache.get(url)
    if strategy == 'cache-first':
        return ('cached', cached) if cached is not None else ('network', url)
    if strategy == 'network-first':
        if network_ok:
            return ('network', url)
        return ('cached', cached) if cached is not None else ('error', url)
    return ('stale', cached) if cached is not None else ('network', url)

