def tls_handshake(state, op):
    # 加密传输：TLS 简化握手状态机（问候→密钥交换→完成→安全通道）
    if op == 'hello':
        state['phase'] = 'hello'
        return 'server_hello'
    if op == 'exchange':
        state['phase'] = 'exchange'
        state['session_key'] = (state.get('client_rand', 0)
                                + state.get('server_rand', 0)) % 256
        return 'key_established'
    if op == 'finish':
        if 'session_key' not in state:
            if 'client_rand' not in state or 'server_rand' not in state:
                return 'not_ready'
            # 防御式：未显式 exchange 时自动协商（状态机容错）
            state['session_key'] = (state['client_rand']
                                    + state['server_rand']) % 256
        state['phase'] = 'secure'
        return 'secure_channel'
    return None

