def mlfq_ops(queues, op, pid=None, level=None, boost_to=0):
    # 多级反馈队列：enqueue 按等级入队 / pick 取最高级队首
    # / boost 低优先级提升（防饿死）
    if op == 'enqueue':
        queues[level].append(pid)
        return queues[level]
    if op == 'pick':
        for q in queues:
            if q:
                return q.pop(0)
        return None
    if op == 'boost':
        if boost_to < len(queues):
            merged = []
            for i in range(boost_to + 1, len(queues)):
                merged.extend(queues[i])
                queues[i] = []
            queues[boost_to].extend(merged)
        return queues[boost_to]
    return None

