def kruskal_mst(edges, n):
    # 最小生成树：Kruskal——按权重升序加边，并查集避环（最小连通代价）
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    total, count = 0, 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            total += w
            count += 1
            if count == n - 1:
                break
    return total, count

