def buddy_alloc(free_lists, size):
    # 伙伴系统：2 的幂块分配（最小合适阶取，缺则高阶分裂回补）
    order = 0
    while (1 << order) < size:
        order += 1
    for o in range(order, max(free_lists) + 1):
        if free_lists[o]:
            free_lists[o] -= 1
            while o > order:
                o -= 1
                free_lists[o] += 1
            return 'allocated'
    return 'failed'

