def query_cache(cache, op, key=None, result=None, capacity=3):
    # 查询缓存：get 命中返回并移末尾 / put 存结果（LRU 淘汰超容量）
    if op == 'get':
        if key in cache:
            val = cache.pop(key)
            cache[key] = val
            return val
        return None
    if op == 'put':
        if key in cache:
            cache.pop(key)
        cache[key] = result
        while len(cache) > capacity:
            cache.pop(next(iter(cache)))
        return len(cache)
    return None

