def varint_codec(n_or_bytes, mode):
    # 紧凑编码：encode 变长整数 / decode 还原（7 位一组，小整数省字节）
    if mode == 'encode':
        out = []
        n = n_or_bytes
        while n >= 128:
            out.append((n & 127) | 128)
            n >>= 7
        out.append(n)
        return bytes(out)
    if mode == 'decode':
        n, shift = 0, 0
        for b in n_or_bytes:
            n |= (b & 127) << shift
            if b < 128:
                return n
            shift += 7
        return n
    return None

