def history_ops(hist, op, url=None):
    # 历史记录：visit 记录 / back 后退 / forward 前进（栈+指针语义）
    if op == 'visit':
        hist['stack'] = hist.get('stack', [])[:hist.get('pos', -1) + 1]
        hist['stack'].append(url)
        hist['pos'] = len(hist['stack']) - 1
        return hist['pos']
    if op == 'back':
        if hist.get('pos', 0) > 0:
            hist['pos'] -= 1
            return hist['stack'][hist['pos']]
        return None
    if op == 'forward':
        stack = hist.get('stack', [])
        pos = hist.get('pos', -1)
        if pos + 1 < len(stack):
            hist['pos'] = pos + 1
            return stack[hist['pos']]
        return None
    return None

