def qos_queue(queues, op, flow=None, priority=None):
    # QoS 队列：classify 流量分类 / enqueue 按优先级入队 / dequeue 高优先先出
    if op == 'classify':
        return 'high' if priority and priority >= 3 else 'low'
    if op == 'enqueue':
        lvl = 'high' if priority and priority >= 3 else 'low'
        queues.setdefault(lvl, []).append(flow)
        return lvl
    if op == 'dequeue':
        for lvl in ('high', 'low'):
            q = queues.get(lvl)
            if q:
                return q.pop(0)
        return None
