def link_aggregation(links, op, link_id=None, data=None):
    # 链路聚合：add 加链路 / send 选最少链路分发（负载均衡）/ fail 故障切换
    if op == 'add':
        links.append({'id': link_id, 'up': True, 'sent': 0})
        return len(links) - 1
    if op == 'send':
        up = [l for l in links if l['up']]
        if not up:
            return 'no_link'
        best = min(up, key=lambda l: l['sent'])
        best['sent'] += 1
        return best['id']
    if op == 'fail':
        for l in links:
            if l['id'] == link_id:
                l['up'] = False
                return 'failed'
        return 'missing'
    return None

