def lex_string(src, i):
    # 字符串字面量：引号内解析（支持反斜杠转义）→ (token, 新位置)
    if src[i] != '"':
        return None, i
    j = i + 1
    buf = []
    while j < len(src) and src[j] != '"':
        if src[j] == '\\' and j + 1 < len(src):
            buf.append(src[j + 1])
            j += 2
        else:
            buf.append(src[j])
            j += 1
    if j >= len(src):
        return ('STRING', ''.join(buf), 'unterminated'), j
    return ('STRING', ''.join(buf)), j + 1

