def lex_number(src, i):
    # 数字字面量：整数/浮点/十六进制解析 → (token, 新位置)
    if src[i] == '0' and i + 1 < len(src) and src[i + 1] in 'xX':
        j = i + 2
        while j < len(src) and (src[j].isdigit() or src[j] in 'abcdefABCDEF'):
            j += 1
        return ('NUMBER', int(src[i + 2:j], 16)), j
    if src[i].isdigit():
        j = i
        while j < len(src) and (src[j].isdigit() or src[j] == '.'):
            j += 1
        text = src[i:j]
        return ('NUMBER', float(text) if '.' in text else int(text)), j
    return None, i

