def max_flow(graph, source, sink):
    # 最大流：Ford-Fulkerson——BFS 增广路径推送（残留网络）
    flow = 0
    while True:
        parent = {source: None}
        queue = [source]
        found = False
        while queue and not found:
            u = queue.pop(0)
            for v, cap in graph.get(u, {}).items():
                if v not in parent and cap > 0:
                    parent[v] = u
                    if v == sink:
                        found = True
                        break
                    queue.append(v)
        if not found:
            break
        v = sink
        path_flow = float('inf')
        while parent[v] is not None:
            u = parent[v]
            path_flow = min(path_flow, graph[u][v])
            v = u
        v = sink
        while parent[v] is not None:
            u = parent[v]
            graph[u][v] -= path_flow
            graph.setdefault(v, {})[u] = graph.get(v, {}).get(u, 0) + path_flow
            v = u
        flow += path_flow
    return flow

