def graph_diameter(adj, n):
    # 图直径：最长最短路径（全源 BFS 最大距离）
    def bfs(s):
        dist = {s: 0}
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v in adj.get(u, []):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return max(dist.values()) if dist else 0
    return max(bfs(i) for i in range(n))

