def link_state_routing(graph, source):
    # 链路状态路由：Dijkstra 最短路径树（OSPF 全拓扑计算）
    dist = {source: 0}
    prev = {}
    unvisited = set(graph)
    while unvisited:
        u = min(unvisited, key=lambda n: dist.get(n, float('inf')))
        unvisited.discard(u)
        for v, w in graph.get(u, {}).items():
            nd = dist.get(u, float('inf')) + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
    return dist, prev

