def async_semaphore(sem, op):
    # 异步信号量：acquire 获取（满则等待）/ release 释放（并发上限）
    if op == 'acquire':
        if sem.get('count', 0) >= sem.get('limit', 1):
            sem['waiting'] = sem.get('waiting', 0) + 1
            return 'waiting'
        sem['count'] = sem.get('count', 0) + 1
        return 'acquired'
    if op == 'release':
        if sem.get('waiting', 0) > 0:
            sem['waiting'] -= 1
            return 'handoff'
        sem['count'] = max(sem.get('count', 0) - 1, 0)
        return 'released'
    return None

