def merge_conditions(cond1, cond2):
    # 条件合并：两条条件链合并（AND 语义——路由条件叠加，冲突拒绝）
    merged = {}
    for k in set(cond1) | set(cond2):
        if k in cond1 and k in cond2 and cond1[k] != cond2[k]:
            return 'conflict'
        merged[k] = cond1.get(k, cond2.get(k))
    return merged

