def trust_propagate(graph, node, trust, decay=0.5):
    # 信任传播：信任沿边衰减传播（信任引擎——多跳信任累积）
    out = {node: trust}
    queue = [(node, trust)]
    while queue:
        u, t = queue.pop(0)
        for v in graph.get(u, []):
            nt = round(t * decay, 3)
            if v not in out or nt > out[v]:
                out[v] = nt
                queue.append((v, nt))
    return out

