def token_ops(tokens, op, token=None, user=None, ttl=0, now=0):
    # 访问令牌：issue 签发 / verify 校验（未过期且有效）/ revoke 吊销
    if op == 'issue':
        tokens[token] = {'user': user, 'expire': now + ttl,
                         'revoked': False}
        return 'issued'
    if op == 'verify':
        t = tokens.get(token)
        if t is None or t.get('revoked'):
            return 'invalid'
        return 'valid' if t['expire'] >= now else 'expired'
    if op == 'revoke':
        if token in tokens:
            tokens[token]['revoked'] = True
            return 'revoked'
        return 'missing'
    return None

