def compress_transfer(data, mode):
    # 压缩传输：compress 行程编码（RLE 重复段）/ decompress 还原
    if mode == 'compress':
        out = []
        i = 0
        while i < len(data):
            j = i
            while j < len(data) and data[j] == data[i]:
                j += 1
            out.append((data[i], j - i))
            i = j
        return out
    if mode == 'decompress':
        return ''.join(c * n for c, n in data)
    return None

