def incremental_backup(backups, op, base=None, changes=None, tag=None):
    # 增量备份：full 全量 / incr 增量（记录变更）/ restore 还原
    if op == 'full':
        backups[tag] = {'type': 'full', 'data': dict(base)}
        return tag
    if op == 'incr':
        backups[tag] = {'type': 'incr', 'base': base,
                        'changes': dict(changes)}
        return tag
    if op == 'restore':
        full = backups.get(base)
        if full is None:
            return None
        data = dict(full['data'])
        incr = backups.get(tag)
        if incr and incr['type'] == 'incr' and incr['base'] == base:
            data.update(incr['changes'])
        return data
    return None

