def snapshot_isolation(versions, op, key=None, value=None, version=None):
    # 一致性快照：版本化读写（读 ≤ 版本最新值——MVCC 快照隔离）
    if op == 'write':
        versions.setdefault(key, {})[version] = value
        return version
    if op == 'read':
        kv = versions.get(key, {})
        if not kv:
            return None
        avail = [v for v in kv if v <= version]
        return kv[max(avail)] if avail else None
    return None

