def consistent_hash(ring, op, node=None, key=None):
    # 一致性哈希：add 节点入环 / locate 键定位（哈希环——最小迁移）
    if op == 'add':
        h = sum(ord(c) for c in node)
        ring[h] = node
        return h
    if op == 'locate':
        if not ring:
            return None
        kh = sum(ord(c) for c in key)
        hs = sorted(ring)
        for h in hs:
            if h >= kh:
                return ring[h]
        return ring[hs[0]]
    return None

