def lex_ident(src, i):
    # 标识符解析：CJK/字母/下划线开头，后接字母数字下划线
    if not (src[i].isalpha() or src[i] == '_'):
        return None, i
    j = i
    while j < len(src) and (src[j].isalpha() or src[j].isdigit()
                             or src[j] == '_'):
        j += 1
    return ('IDENT', src[i:j]), j

