def lex_op(src, i):
    # 操作符解析：多字符操作符优先（>= <= == != 先匹配双字符）
    two = src[i:i + 2]
    if two in ('>=', '<=', '==', '!='):
        return ('OP', two), i + 2
    if src[i] in '+-*/<>=':
        return ('OP', src[i]), i + 1
    return None, i

