def neighbor_query(adj, op, node=None, hops=1):
    # 邻居查询：direct 一跳邻居 / multi 多跳邻居（BFS 扩展）
    if op == 'direct':
        return sorted(adj.get(node, []))
    if op == 'multi':
        seen = {node}
        frontier = [node]
        for _ in range(hops):
            nxt = []
            for u in frontier:
                for v in adj.get(u, []):
                    if v not in seen:
                        seen.add(v)
                        nxt.append(v)
            frontier = nxt
        seen.discard(node)
        return sorted(seen)
    return None

