def triangle_count(adj, n):
    # 三角形计数：闭合三元组（聚类检测——社交网络三角）
    triangles = 0
    for u in range(n):
        for v in adj.get(u, []):
            if v > u:
                for w in adj.get(v, []):
                    if w > v and w in adj.get(u, []):
                        triangles += 1
    return triangles

