def stack_ops(stack, op):
    # 栈操作：DUP 复制栈顶 / SWAP 交换栈顶两元素（栈指令）
    if op == 'DUP':
        if not stack:
            return None
        stack.append(stack[-1])
        return stack[-1]
    if op == 'SWAP':
        if len(stack) < 2:
            return None
        stack[-1], stack[-2] = stack[-2], stack[-1]
        return stack[-2]
    return None

domain:compiler|VM-算术执行.code:
def arith_exec(stack, op):
    # 算术执行：弹出两操作数执行 ADD/SUB/MUL/DIV（栈机算术指令）
    if len(stack) < 2:
        return None
    b = stack.pop()
    a = stack.pop()
    if op == 'ADD':
        r = a + b
    elif op == 'SUB':
        r = a - b
    elif op == 'MUL':
        r = a * b
    elif op == 'DIV':
        r = a / b
    else:
        return None
    stack.append(r)
    return r

