def cmp_exec(stack, op):
    # 比较执行：弹出两操作数比较 LT/GT/EQ（栈机比较指令→布尔）
    if len(stack) < 2:
        return None
    b = stack.pop()
    a = stack.pop()
    if op == 'LT':
        r = a < b
    elif op == 'GT':
        r = a > b
    elif op == 'EQ':
        r = a == b
    else:
        return None
    stack.append(r)
    return r

