def chunked_transfer(op, data=None, chunk_size=0):
    # 分块传输：encode 分块编码（每块十六进制长度）/ decode 还原
    if op == 'encode':
        chunks = [data[i:i + chunk_size]
                  for i in range(0, len(data), chunk_size)]
        return ''.join(f'{len(c):x}\\r\\n{c}\\r\\n' for c in chunks) \
            + '0\\r\\n\\r\\n'
    if op == 'decode':
        out = []
        i = 0
        while i < len(data):
            j = data.index('\\r\\n', i)
            size = int(data[i:j], 16)
