def storage_pool(pool, op, name=None, size=0):
    # 存储池：create 建池 / alloc 分配（容量扣减）/ free 释放 / status 状态
    if op == 'create':
        pool[name] = {'total': size, 'used': 0}
        return name
    if op == 'alloc':
        p = pool.get(name)
        if p is None:
            return 'missing'
        if p['used'] + size > p['total']:
            return 'insufficient'
        p['used'] += size
        return 'allocated'
    if op == 'free':
        p = pool.get(name)
        if p is None:
            return 'missing'
        p['used'] = max(p['used'] - size, 0)
        return 'freed'
    if op == 'status':
        p = pool.get(name)
        return dict(p) if p else None
    return None

