def unescape(text):
    # 转义序列：反斜杠n 反斜杠t 反斜杠引号 解码（字符串转义处理）
    out = []
    i = 0
    while i < len(text):
        if text[i] == '\\' and i + 1 < len(text):
            nxt = text[i + 1]
            if nxt == 'n':
                out.append(chr(10))
            elif nxt == 't':
                out.append(chr(9))
            elif nxt == chr(34):
                out.append(chr(34))
            else:
                out.append(nxt)
            i += 2
        else:
            out.append(text[i])
            i += 1
    return ''.join(out)

