def base_convert(value, base, to_text=True):
    # 进制转换：to_text 十进制→base 进制字符串 / 反向解析为十进制
    digits = '0123456789abcdef'
    if to_text:
        if value == 0:
            return '0'
        out = []
        n = value
        while n > 0:
            out.append(digits[n % base])
            n //= base
        return ''.join(reversed(out))
    total = 0
    for ch in value:
        total = total * base + digits.index(ch)
    return total

