def scc_kosaraju(graph):
    # 强连通分量：Kosaraju 两遍 DFS（反向图第二次遍历收集 SCC）
    visited = set()
    order = []
    def dfs(u, g, out):
        visited.add(u)
        for v in g.get(u, []):
            if v not in visited:
                dfs(v, g, out)
        out.append(u)
    for u in graph:
        if u not in visited:
            dfs(u, graph, order)
    rev = {}
    for u, vs in graph.items():
        for v in vs:
            rev.setdefault(v, []).append(u)
    visited.clear()
    comps = []
    for u in reversed(order):
        if u not in visited:
            comp = []
            dfs(u, rev, comp)
            comps.append(comp)
    return comps

