def bipartite_matching(adj, left):
    # 二分匹配：增广路查找最大匹配（left 集合顶点 → 唯一 right 顶点）
    match = {}
    def try_k(u, seen):
        for v in adj.get(u, []):
            if v in seen:
                continue
            seen.add(v)
            if v not in match or try_k(match[v], seen):
                match[v] = u
                return True
        return False
    count = 0
    for u in left:
        if try_k(u, set()):
            count += 1
    return count

