def btree_ops(values, op):
    # 二叉树：build 有序列表→BST 插入 / inorder 中序遍历（二叉搜索树）
    def insert(node, v):
        if node is None:
            return {'v': v, 'l': None, 'r': None}
        if v < node['v']:
            node['l'] = insert(node['l'], v)
        else:
            node['r'] = insert(node['r'], v)
        return node
    def inorder(node):
        if node is None:
            return []
        return inorder(node['l']) + [node['v']] + inorder(node['r'])
    if op == 'build':
        root = None
        for v in values:
            root = insert(root, v)
        return root
    if op == 'inorder':
        return inorder(values)
    return None

