def heap_ops(heap, op, item=None):
    # 最小堆：push 上浮插入 / pop 根最小弹出 / peek 查看根（堆机制）
    def up(i):
        while i > 0:
            p = (i - 1) // 2
            if heap[p] <= heap[i]:
                break
            heap[p], heap[i] = heap[i], heap[p]
            i = p
    def down(i):
        n = len(heap)
        while True:
            l, r, m = 2 * i + 1, 2 * i + 2, i
            if l < n and heap[l] < heap[m]:
                m = l
            if r < n and heap[r] < heap[m]:
                m = r
            if m == i:
                break
            heap[i], heap[m] = heap[m], heap[i]
            i = m
    if op == 'push':
        heap.append(item)
        up(len(heap) - 1)
        return heap[0]
    if op == 'pop':
        if not heap:
            return None
        root = heap[0]
        last = heap.pop()
        if heap:
            heap[0] = last
            down(0)
        return root
    if op == 'peek':
        return heap[0] if heap else None
    return None

