def transitive_closure(adj, n):
    # 传递闭包：Floyd-Warshall 布尔可达闭包（可达性矩阵）
    reach = [[False] * n for _ in range(n)]
    for i in range(n):
        reach[i][i] = True
    for u in adj:
        for v in adj[u]:
            reach[u][v] = True
    for k in range(n):
        for i in range(n):
            for j in range(n):
                reach[i][j] = reach[i][j] or (reach[i][k] and reach[k][j])
    return reach

