def min_cut(adj, s, t):
    # 最小割：最大流=最小割（BFS 找增广路累加容量）
    flow = 0
    cap = {u: dict(vs) for u, vs in adj.items()}
    while True:
        parent = {}
        q = [s]
        seen = {s}
        while q and t not in parent:
            u = q.pop(0)
            for v, c in cap.get(u, {}).items():
                if v not in seen and c > 0:
                    seen.add(v)
                    parent[v] = u
                    q.append(v)
        if t not in parent:
            break
        path_flow = float('inf')
        v = t
        while v != s:
            u = parent[v]
            path_flow = min(path_flow, cap[u][v])
            v = u
        v = t
        while v != s:
            u = parent[v]
            cap[u][v] -= path_flow
            cap.setdefault(v, {})[u] = cap.get(v, {}).get(u, 0) + path_flow
            v = u
        flow += path_flow
    return flow

