def betweenness(adj):
    # 介数中心性：节点出现在最短路径中的次数（桥梁重要性）
    nodes = list(adj)
    score = {n: 0.0 for n in nodes}
    for s in nodes:
        for t in nodes:
            if s >= t:
                continue
            paths = []
            q = [(s, [s])]
            best = None
            while q:
                u, p = q.pop(0)
                if u == t:
                    if best is None or len(p) == best:
                        best = len(p)
                        paths.append(p)
                    elif len(p) > best:
                        continue
                for v in adj.get(u, []):
                    if v not in p:
                        q.append((v, p + [v]))
            n_paths = len(paths)
            if not n_paths:
                continue
            for p in paths:
                for m in p[1:-1]:
                    score[m] += 1.0 / n_paths
    return {n: round(v, 2) for n, v in score.items()}

