def dominator_tree(adj, entry):
    # 支配树：入口可达必经节点（支配关系——必经点）
    nodes = list(adj)
    dom = {n: set(nodes) for n in nodes}
    dom[entry] = {entry}
    changed = True
    while changed:
        changed = False
        for n in nodes:
            if n == entry:
                continue
            preds = [p for p in nodes if n in adj.get(p, [])]
            if not preds:
                continue
            new = {n} | set.intersection(*(dom[p] for p in preds))
            if new != dom[n]:
                dom[n] = new
                changed = True
    return dom

