def articulation_points(adj):
    # 割点：移除后图不连通的顶点（Tarjan DFS low 值）
    n = len(adj)
    disc = {}
    low = {}
    time = [0]
    out = set()
    def dfs(u, parent):
        disc[u] = low[u] = time[0]
        time[0] += 1
        children = 0
        for v in adj.get(u, []):
            if v == parent:
                continue
            if v not in disc:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if parent is None and children > 1:
                    out.add(u)
                if parent is not None and low[v] >= disc[u]:
                    out.add(u)
            else:
                low[u] = min(low[u], disc[v])
    for u in adj:
        if u not in disc:
            dfs(u, None)
    return sorted(out)

