def a_star(adj, start, goal, h):
    # 路径规划：A* 启发式搜索（f=g+h 优先队列）
    open_set = [(h(start), 0, start, [start])]
    seen = set()
    while open_set:
        open_set.sort(key=lambda x: x[0])
        f, g, u, path = open_set.pop(0)
        if u == goal:
            return path
        if u in seen:
            continue
        seen.add(u)
        for v, w in adj.get(u, []):
            if v not in seen:
                ng = g + w
                open_set.append((ng + h(v), ng, v, path + [v]))
    return None

