    path = [start]
    seen = {start}
    cur = start
    while len(path) < len(adj):
        nxt = None
        for v, w in sorted(adj.get(cur, []), key=lambda x: x[1]):
            if v not in seen:
                nxt = v
                break
        if nxt is None:
            break
        path.append(nxt)
        seen.add(nxt)
        cur = nxt
    return path

