        cur = state.get('level', 0)
        if cur + 1 <= state.get('size', size):
            state['level'] = cur + 1
            return True
        return False
    if op == 'leak':
        cur = state.get('level', 0)
        state['level'] = max(0, cur - state.get('rate', rate))
        return state['level']
    if op == 'accept':
        return state.get('level', 0) < state.get('size', size)
    return None

