def wfq_schedule(queues, op, weights=None):
    # 报文调度：dequeue 按权重选队列 / enqueue 入队 / weights 查询（WFQ 加权公平）
    if op == 'enqueue':
        return queues
    if op == 'dequeue':
        w = weights or {k: 1 for k in queues}
        best = max(queues, key=lambda k: w.get(k, 1) if queues[k] else -1)
