def rle_codec(data, op):
    # 行程压缩：encode 连续值计数 / decode 还原（run-length encoding）
    if op == 'encode':
        out = []
        i = 0
        while i < len(data):
            j = i
            while j < len(data) and data[j] == data[i]:
                j += 1
            out.append((data[i], j - i))
            i = j
        return out
    if op == 'decode':
        out = []
        for ch, n in data:
            out.extend([ch] * n)
        return out
    return None

