def percentile(data, p):
    # 分位数：排序后按百分位取位置（statistics.quantiles 语义）
    if not data:
        return None
    s = sorted(data)
    k = (len(s) - 1) * p / 100.0
    lo = int(k)
    hi = min(lo + 1, len(s) - 1)
    frac = k - lo
    return round(s[lo] + (s[hi] - s[lo]) * frac, 2)

