def graphic_sequence(degrees):
    # 度序列：Havel-Hakimi 判断是否可图化（简单图存在性）
    d = sorted(degrees, reverse=True)
    while d:
        if d[0] < 0 or d[0] >= len(d):
            return False
        n = d.pop(0)
        if n == 0:
            continue
        if n > len(d):
            return False
        for i in range(n):
            d[i] -= 1
        d.sort(reverse=True)
    return True

