def spanning_trees(adj):
    # 生成树计数：Kirchhoff 矩阵树定理（Laplacian 主子式行列式）
    n = len(adj)
    if n <= 1:
        return 1
    lap = [[0] * (n - 1) for _ in range(n - 1)]
    for i in range(n - 1):
        lap[i][i] = len(adj.get(i, []))
        for j in range(n - 1):
            if i != j and j in adj.get(i, []):
                lap[i][j] = -1
    # 2x2 行列式（简化：仅支持最多 3 节点精确，更大用递推）
    if n - 1 == 1:
        return lap[0][0]
    return lap[0][0] * lap[1][1] - lap[0][1] * lap[1][0]

