def count_paths(adj, start, end, max_len=4):
    # 路径计数：DFS 简单路径枚举计数（长度上限）
    def dfs(u, seen, depth):
        if depth > max_len:
            return 0
        if u == end:
            return 1
        total = 0
        for v in adj.get(u, []):
            if v not in seen:
                seen.add(v)
                total += dfs(v, seen, depth + 1)
                seen.remove(v)
        return total
    return dfs(start, {start}, 0)

