def hamiltonian(adj):
    # 汉密尔顿路径：访问每个顶点恰好一次（回溯搜索）
    nodes = list(adj)
    n = len(nodes)
    if n == 0:
        return []
    def dfs(u, seen, path):
        if len(path) == n:
            return path
        for v in adj.get(u, []):
            if v not in seen:
                seen.add(v)
                r = dfs(v, seen, path + [v])
                if r:
                    return r
                seen.remove(v)
        return None
    for s in nodes:
        r = dfs(s, {s}, [s])
        if r:
            return r
    return None

