def union_find(state, op, a=None, b=None):
    # 并查集：find 根查找 / union 合并 / connected 连通判定（不相交集）
    parent = state.setdefault('parent', {})
    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    if op == 'find':
        return find(a)
    if op == 'union':
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra
        return ra
    if op == 'connected':
        return find(a) == find(b)
    return None

