def trust_flow(expr, env):
    # 德：编译期信任传播（与=取min，或=取max，非=1-t，名=查env，字面量=1.0）
    if isinstance(expr, tuple):
        op = expr[0]
        if op == "AND":
            return min(trust_flow(expr[1], env), trust_flow(expr[2], env))
        if op == "OR":
            return max(trust_flow(expr[1], env), trust_flow(expr[2], env))
        if op == "NOT":
            return round(1.0 - trust_flow(expr[1], env), 3)
    if isinstance(expr, str):
        return env.get(expr, 0.0)
    return 1.0

domain:compiler|VM-短路求值.code:
def vm_short_circuit(left, op, right):
    # 短路求值：与=左假不求右，或=左真不求右（VM 逻辑执行语义）
    # 返回 (结果, 右操作数是否被求值)
    if op == '且':
        if not left:
            return (False, False)
        return (bool(right), True)
    if op == '或':
        if left:
            return (True, False)
        return (bool(right), True)
    return (None, False)

