def unpack_assign(targets, values):
    # 解包赋值：a, b = b, a 多重赋值/嵌套解包（P 线赋值机制）
    out = {}
    def walk(ts, vs):
        for t, v in zip(ts, vs):
            if isinstance(t, list):
                walk(t, v)
            else:
                out[t] = v
    walk(targets, values)
    return out

