def vertex_cover(edges):
    # 顶点覆盖：贪心选边两端加入覆盖并删去关联边（2-近似）
    cover = set()
    e = [list(ed) for ed in edges]
    while e:
        u, v = e[0]
        cover.add(u)
        cover.add(v)
        e = [ed for ed in e if u not in ed and v not in ed]
    return sorted(cover)

domain:graph|图算法-最近公共祖先.code:
def lca(parent, depth, a, b):
    # 最近公共祖先：深度对齐后同步上溯（树上查询）
    while depth[a] > depth[b]:
        a = parent[a]
    while depth[b] > depth[a]:
        b = parent[b]
    while a != b:
        a = parent[a]
        b = parent[b]
    return a

