domain:os|中断-软中断.code:
def softirq(queue, action, item=None):
    # 软中断：硬中断中延迟的低优先级工作（defer 入队按优先级 / run 依次处理）
    if action == 'defer':
        queue.append(item)
        queue.sort(key=lambda x: x[0])
        return len(queue)
    if action == 'run':
        out = []
        while queue:
            out.append(queue.pop(0))
        return out
    return None

domain:os|调度-工作窃取.code:
def work_steal(queues, worker):
    # 工作窃取：空闲核从最忙队列窃取一个任务（多核负载均衡）
    if queues[worker]:
        return queues
    candidates = [(i, q) for i, q in enumerate(queues) if q and i != worker]
    if not candidates:
        return queues
    busiest = max(candidates, key=lambda x: len(x[1]))[0]
    queues[worker].append(queues[busiest].pop(0))
    return queues

