def ws_frame_parse(frame):
    # WebSocket 帧解析：FIN/opcode/长度/载荷（RFC 6455 解码——帧封装的逆）
    fin = (frame[0] >> 7) & 1
    opcode = frame[0] & 0x0F
    n = frame[1] & 0x7F
    off = 2
    if n == 126:
        n = int.from_bytes(frame[2:4], 'big')
        off = 4
    elif n == 127:
        n = int.from_bytes(frame[4:12], 'big')
        off = 10
    return (fin, opcode, n, frame[off:off + n].decode('utf-8', 'replace'))

